//! Independent reference values for the EWMA and CUSUM charts.
//!
//! `tests/reference/control_cusum.json` is generated by
//! `tools/gen_control_cusum.py` from the standard formulas; the test never
//! runs Python.

use fp_core::data::Sample;
use fp_core::spc::{self, CusumOptions, EwmaOptions, TestSet};
use serde_json::Value;

fn reference() -> Value {
    let raw = include_str!("reference/control_cusum.json");
    serde_json::from_str(raw).expect("valid JSON reference")
}

fn close(actual: f64, expected: f64, tolerance: f64, what: &str) {
    assert!(
        (actual - expected).abs() <= tolerance,
        "{what}: {actual} vs reference {expected}"
    );
}

fn sample(values: &Value) -> Sample {
    Sample::from_valid(
        values
            .as_array()
            .expect("values")
            .iter()
            .map(|value| value.as_f64().expect("value"))
            .collect(),
        0,
    )
    .expect("sample")
}

#[test]
fn the_ewma_chart_matches_the_standard_formulas() {
    let r = reference();
    let tolerance = 1e-12;
    let sample = sample(&r["values"]);
    let options = EwmaOptions::new(
        r["lambda"].as_f64().expect("lambda"),
        r["limit"].as_f64().expect("limit"),
    )
    .expect("options");
    let chart =
        spc::ewma_chart_with_options(&sample, TestSet::default(), options).expect("ewma chart");

    close(
        chart.sigma,
        r["sigma"].as_f64().expect("sigma"),
        tolerance,
        "sigma",
    );
    let expected = r["ewma"].as_array().expect("ewma");
    assert_eq!(chart.location.len(), expected.len());
    for (index, (actual, expected)) in chart.location.iter().zip(expected).enumerate() {
        close(
            *actual,
            expected.as_f64().expect("z"),
            tolerance,
            &format!("z[{}]", index + 1),
        );
    }
    close(
        chart.location_limits.center,
        r["mean"].as_f64().expect("mean"),
        tolerance,
        "center",
    );
    let asymptotic = r["ewma_asymptotic"].as_f64().expect("asymptotic");
    close(
        chart.location_limits.ucl - chart.location_limits.center,
        asymptotic,
        tolerance,
        "asymptotic half-width",
    );

    let limits = r["ewma_limits"].as_array().expect("limits");
    let mut expected_signals = 0;
    for (index, (value, limits)) in chart.location.iter().zip(limits).enumerate() {
        let low = limits[0].as_f64().expect("low");
        let high = limits[1].as_f64().expect("high");
        if *value < low || *value > high {
            expected_signals += 1;
            let _ = index;
        }
    }
    assert_eq!(chart.signals.len(), expected_signals);
}

#[test]
fn the_cusum_chart_matches_the_standard_formulas() {
    let r = reference();
    let tolerance = 1e-12;
    let sample = sample(&r["values"]);
    let options = CusumOptions::new(r["k"].as_f64().expect("k"), r["h"].as_f64().expect("h"))
        .expect("options");
    let chart = spc::cusum_chart_with_options(&sample, 1, options).expect("cusum chart");

    close(
        chart.sigma,
        r["sigma"].as_f64().expect("sigma"),
        tolerance,
        "sigma",
    );
    let upper = r["cusum_upper"].as_array().expect("upper");
    let lower = r["cusum_lower"].as_array().expect("lower");
    assert_eq!(chart.location.len(), upper.len());
    assert_eq!(chart.dispersion.len(), lower.len());
    for (index, (actual, expected)) in chart.location.iter().zip(upper).enumerate() {
        close(
            *actual,
            expected.as_f64().expect("upper"),
            tolerance,
            &format!("C+[{}]", index + 1),
        );
    }
    for (index, (actual, expected)) in chart.dispersion.iter().zip(lower).enumerate() {
        close(
            *actual,
            expected.as_f64().expect("lower"),
            tolerance,
            &format!("C-[{}]", index + 1),
        );
    }
    close(
        chart.location_limits.ucl,
        r["h"].as_f64().expect("h"),
        tolerance,
        "decision interval",
    );
}
